function t2course(name='Schooling Course'){return {id:`course-${++t2state().sequence}`,name,discipline:'jumping',location:'Outdoor',obstacles:[]};}
function t2fence(course,extra={}){const fence={id:`fence-${++t2state().sequence}`,type:'vertical',height:.5,width:.5,distance:10,direction:'Left',combination:null,filler:false,...extra};course.obstacles.push(fence);return fence;}
function t2courseEdit(course,index,action,value){const fence=course.obstacles[index];if(action==='add')return t2fence(course);if(!fence)return false;if(action==='uncombine')fence.combination=null;else if(action==='remove')course.obstacles.splice(index,1);else if(action==='up'&&index>0)[course.obstacles[index-1],course.obstacles[index]]=[fence,course.obstacles[index-1]];else if(action==='down'&&index<course.obstacles.length-1)[course.obstacles[index+1],course.obstacles[index]]=[fence,course.obstacles[index+1]];else if(['height','width','distance'].includes(action)){if(!Number.isFinite(Number(value))||Number(value)<0)return false;fence[action]=Number(value);}else if(action==='raise5'||action==='lower5'||action==='raise10'||action==='lower10')fence.height=Math.max(0,Math.round((fence.height+(action.startsWith('lower')?-1:1)*(action.endsWith('10')?.10:.05))*100)/100);else if(['type','direction','combination','filler'].includes(action))fence[action]=value;return true;}
