function t2options(values,current){return values.map(v=>`<option value='${mgEscape(String(typeof v==='object'?v.id:v))}' ${String(typeof v==='object'?v.id:v)===String(current)?'selected':''}>${mgEscape(String(typeof v==='object'?v.name:v))}</option>`).join('');}
function t2button(action,label){return `<button type='button' data-t2-action='${action}'>${label}</button>`;}
function t2reportMarkup(r){return `<details class='box' data-ui-key='training2-report' open><summary>TRAINING REPORT — ${mgEscape(r.horseName)}</summary><p>Horse: ${mgEscape(r.horseName)}<br>Discipline: ${mgEscape(r.discipline)}<br>Location: ${mgEscape(r.location)}<br>Weather: ${mgEscape(r.weather)}<br>Session Duration: ${t2fmt(r.duration)} minutes<br>Exercises Completed: ${r.exercises.filter(x=>['Clean/Correct','Correct with minor imperfection','Partial execution','Technical mistake'].includes(x.result)).length}</p><h4>Exercise Summary</h4>${r.exercises.map(x=>`<p>${mgEscape(x.name)} — ${x.result}</p>`).join('')}<h4>Technique</h4>${r.exercises.map(x=>`<p>${mgEscape(x.text)}</p>`).join('')}<h4>Progress</h4>${Object.entries(r.progress).map(([k,v])=>`<p>${mgEscape(k)}: +${k.startsWith('Riding ')?t2attributeFmt(v):t2fmt(v)}</p>`).join('')||'<p>No earned progress.</p>'}<p>Fatigue: ${t2fmt(r.fatigue[0])} → ${t2fmt(r.fatigue[1])}<br>Mood: ${mgEscape(r.mood[0])} → ${mgEscape(r.mood[1])}</p><h4>Trainer’s Notes</h4>${r.notes.map(n=>`<p>${mgEscape(n)}</p>`).join('')||'<p>Continue suitable varied work and monitor fatigue.</p>'}<h4>Next Suggested Exercises</h4><p>${r.suggestions.map(mgEscape).join(', ')}</p></details>`;}
function t2setupMarkup(setup,prefix='t2'){return `<div class='grid three'><label>Fence Type<select id='${prefix}-type'>${t2options(['crossrail','vertical','oxer','plank','filler','water'],setup.type)}</select></label><label>Fence Height<input id='${prefix}-height' type='number' min='0' max='1.8' step='.05' value='${setup.height}'></label><label>Fence Width<input id='${prefix}-width' type='number' min='0' max='2' step='.05' value='${setup.width}'></label><label>Distance to Next Fence<input id='${prefix}-distance' type='number' min='0' max='50' step='.1' value='${setup.distance}'></label><label>Approach Direction<select id='${prefix}-direction'>${t2options(['Left','Right','Straight'],setup.direction)}</select></label></div>`;}
function t2readSetup(panel,prefix='t2'){return Object.fromEntries(['type','height','width','distance','direction'].map(k=>[k,['height','width','distance'].includes(k)?Number(panel.querySelector(`#${prefix}-${k}`).value):panel.querySelector(`#${prefix}-${k}`).value]));}
function t2attributesMarkup(h){return `<details class='box' data-ui-key='riding-attributes'><summary>Riding Attributes & Individual Traits</summary><div class='grid two'>${T2_ATTRIBUTES.map(a=>`<p><strong>${a}</strong> ${t2attributeFmt(t2attribute(h,a))}/10.0 — ${t2description(t2attribute(h,a))}<br><span class='small'>${a==='Sensitivity to Aids'?'Mostly innate; match cue intensity.':T2_EXERCISES.filter(e=>e.primary===a||e.secondary===a).slice(0,3).map(e=>e.name).join(', ')||'Calm walk breaks and suitable exposure.'}</span></p>`).join('')}</div><p>Leg understanding ${t2attributeFmt(t2horse(h).education.leg)}/100 · Rein understanding ${t2attributeFmt(t2horse(h).education.rein)}/100</p><p>Individual traits: ${t2horse(h).traits.map(mgEscape).join(', ')||'None'}</p><details><summary>Trait Effects & Schooling Progress</summary>${t2horse(h).traits.map(name=>{const r=T2_TRAIT_RULES.find(r=>r[0]===name);return `<p><strong>${mgEscape(name)}</strong> — ${r[2]>0?'+':''}${r[2]} ${r[1]==='learn'?'% relative':r[1]==='recovery'?'tension recovery points':'pp'} to relevant ${r[1]} only (${T2_CONTEXT_LABELS[r[3]]||r[3].replace(/([A-Z])/g,' $1').toLowerCase()}). Qualifying schooling efforts: ${t2horse(h).habits[name]?.efforts||0}.</p>`;}).join('')}</details><details><summary>Exercise Memory</summary>${Object.entries(t2horse(h).familiarity).map(([k,v])=>`<p>${mgEscape(k)}: ${t2attributeFmt(v)}/100</p>`).join('')||'No new observations recorded.'}</details></details>`;}
function t2trainingHorses(){const scope=app.trainingHorseScope||'both';return [...(scope==='lesson'?[]:app.horses),...(scope==='private'?[]:currentBarnLessonHorses())].filter(h=>!h.deceased);}
function t2findHorse(id){return [...app.horses,...Object.values(app.lessonHorsesByBarn||{}).flat()].find(h=>h.id===id);}
function t2disciplineExercise(e,d){if(!e)return false;if(e.id.startsWith('lunge-')&&!['lunging','groundwork'].includes(d))return false;return d==='lunging'?e.id.startsWith('lunge-'):d==='groundwork'?e.category==='Groundwork':d==='dressage'||d==='flatwork'?['Groundwork','Flatwork','Polework'].includes(e.category):true;}
