const T2_OLD_STALL_MARKUP=stallMarkup;
stallMarkup=function(){let html=T2_OLD_STALL_MARKUP();if(!app.settings.stallAssignments)return html;for(const st of stallState()){if(!Object.values(st.decorations||{}).some(id=>mgOwned(id)?.type==='Wooden Stall Nameplate'))continue;const h=stallOccupants(st)[0];if(h)html=html.replace(`<strong>Stall ${st.number}</strong>`,`<strong>Stall ${st.number}</strong><div class='nameplate-preview'>${t2nameplate(h).map(mgEscape).join('<br>')}</div>`);}return html;};
const T2_OLD_CARE_FACTORS=careCurrentMoodFactors;
careCurrentMoodFactors=function(h){const factors=T2_OLD_CARE_FACTORS(h);if(!h.training2)return factors;const rug=t2rug(h,careNow());if(!rug.comfortable)factors.push({id:'weather_rug_comfort',label:rug.message,mood:'Uncomfortable',pp:2});if((h.fatigue||0)>=70)factors.push({id:'recent_training_fatigue',label:'Recent intensive training has increased fatigue.',mood:'No energy',pp:3});return factors;};
const T2_OLD_MOOD_DISTRIBUTION=careMoodDistribution;
careMoodDistribution=function(h){const p=T2_OLD_MOOD_DISTRIBUTION(h);if(!h.training2||(h.illnesses||[]).some(i=>i.active)&&h.mood==='Distress'||mgEquipmentMoodModifiers(h).forceUncomfortable)return p;const rug=t2rug(h,careNow());return mgShiftMoodWeights(p,{Uncomfortable:rug.comfortable?0:2,'No energy':(h.fatigue||0)>=70?3:0},0);};
const T2_OLD_HOUR=simulatePastureHour;
simulatePastureHour=function(hour){t2weather(hour);for(const h of app.horses){if(h.deceased)continue;t2importLegacySchedule(h);if(h.training2?.scheduleEnabled)t2scheduleRun(h,hour);}const result=T2_OLD_HOUR(hour);for(const h of app.horses){if(h.deceased)continue;if(h.training2&&hour%24===23){h.fatigue=0;h.training2.lastRestDay=Math.floor(hour/24);}}return result;};
const T2_OLD_SKIP=simulatePastureUntil;
