function t2facilityMarkup(){return `<details class='box' data-ui-key='training-facilities'><summary>Training Locations — Indoor / Outdoor</summary><p class='small'>Designate the existing training spaces at this barn. Ratings do not change training performance.</p>${t2facilities().map((f,i)=>`<label>Location Name<input data-t2-facility-name='${i}' value='${mgEscape(f.name)}'></label><label>Indoor / Outdoor<select data-t2-facility-location='${i}'>${t2options(['Indoor','Outdoor'],f.location)}</select></label>`).join('')}<button id='t2-save-facilities'>Save Location Settings</button><button id='t2-add-facility'>Add Existing Training Location</button></details>`;}
function t2bindFacilities(panel){const save=panel.querySelector('#t2-save-facilities');if(save)save.onclick=()=>{const facilities=t2facilities();panel.querySelectorAll('[data-t2-facility-name]').forEach(n=>facilities[Number(n.dataset.t2FacilityName)].name=n.value);panel.querySelectorAll('[data-t2-facility-location]').forEach(n=>facilities[Number(n.dataset.t2FacilityLocation)].location=n.value);saveGame(false);renderTraining();};const add=panel.querySelector('#t2-add-facility');if(add)add.onclick=()=>{t2facilities().push({id:'arena-'+ ++t2state().sequence,name:'Existing Indoor Arena',location:'Indoor',equipment:['flatwork','poles','jumps']});saveGame(false);renderTraining();};}
// Flavor selection consumes exactly the selected physical refill, never a generated copy.
const T2_OLD_BIND_STALLS=bindStalls;
bindStalls=function(panel){T2_OLD_BIND_STALLS(panel);panel.querySelectorAll('[data-likit-refill]').forEach(button=>{const holder=mgOwned(button.dataset.likitRefill);if(!holder)return;const select=document.createElement('select');select.setAttribute('aria-label','Likit refill flavor');select.dataset.likitFlavor=holder.id;select.innerHTML=mgState().items.filter(i=>i.type==='Likit Refill'&&!i.consumed).map(i=>`<option value='${mgEscape(i.id)}'>${mgEscape(i.size)} (${mgEscape(i.id)})</option>`).join('');button.before(select);button.onclick=()=>{const refill=mgOwned(select.value);if(!refill||refill.consumed)return alert('Purchase a Likit Refill in Town → Tack Shop.');refill.consumed=true;holder.refillFlavor=refill.size;holder.refillHours=0;saveGame(false);render();};});};
const T2_OLD_BEHAVIOR_STORE=behaviorStore;
behaviorStore=function(event,horses,location,...rest){if(location==='Stall'&&/Likit/i.test(event.title||'')){const h=horses?.[0],stall=h&&stallHorse(h),holder=stall&&stallActiveSupplies(stall).find(i=>i.type==='Likit Treat Holder');if(h&&holder){const flavor=String(holder.refillFlavor||'').toLowerCase();event.description=holder.refillFlavor===h.dislikedLikitFlavor?`${h.name} shows little interest in this ${flavor} Likit flavor.`:h.decorationPreferences?.['Likit Treat Holder']==='Likes'?`${h.name} spends several minutes investigating the ${flavor} Likit.`:`${h.name} ignores the offered ${flavor} Likit.`;}}return T2_OLD_BEHAVIOR_STORE(event,horses,location,...rest);};
function t2incidentProfile(risk,equipmentPP=0,exposure=1,protection=1){const base=T2.incident[risk]*clamp(exposure,0,1),incident=Math.max(base,equipmentPP/100);return {incident,conversion:incident?clamp((base*T2.conversion[risk]*protection+equipmentPP/100)/incident,0,1):0};}
function t2extraActions(h,s){const e=t2exercise(s.exerciseId);if(e.category==='Jumping')return [['crossrail','Change to Crossrail'],['vertical','Change to Vertical'],['oxer','Change to Oxer'],['ground-pole','Add Ground Pole'],['remove-ground-pole','Remove Ground Pole'],['cavaletti','Replace with Cavaletti'],['gait','Change Approach Gait'],['repeat-line','Repeat the Line'],['remove-filler','Remove Filler'],['intro-filler','Introduce Filler Separately'],['different-fence','Jump a Different Fence']];if(e.category==='Groundwork')return [['calm-repeat','Repeat Calmly'],['smaller-steps','Break Exercise into Smaller Steps'],['object','Change Object'],['away-object','Increase Distance from Object'],['approach-object','Approach Object Gradually'],['familiar','Return to Familiar Exercise']];return [['upward','Ask for Upward Transition'],['downward','Ask for Downward Transition'],['larger-circle','Ride a Larger Circle'],['smaller-circle','Ride a Smaller Circle'],['change-rein','Change Rein'],['serpentine','Add Serpentine'],['lengthen','Lengthen Stride'],['shorten','Shorten Stride'],['halt','Practice Halt'],['back','Practice Rein-Back'],['easier','Return to Easier Movement']].filter(([a])=>{const id=({upward:'walk-trot',downward:'downward','larger-circle':'large-circle','smaller-circle':'small-circle','change-rein':'change-rein',serpentine:'serpentines',lengthen:'lengthen',shorten:'shorten',halt:'walk-halt',back:'rein-back',easier:'large-circle'})[a];return !t2eligibility(h,t2exercise(id),{location:s.location});});}
function t2adjust(h,s,action){const map={upward:'walk-trot',downward:'downward','larger-circle':'large-circle','smaller-circle':'small-circle','change-rein':'change-rein',serpentine:'serpentines',lengthen:'lengthen',shorten:'shorten',halt:'walk-halt',back:'rein-back',easier:'large-circle',crossrail:'crossrail',vertical:'vertical',oxer:'oxer',cavaletti:'cavaletti','intro-filler':'desensitize',familiar:'leading'};if(map[action]){const e=t2exercise(map[action]),error=t2eligibility(h,e,{...s.setup,location:s.location});if(error){s.log.push({kind:'Safety stop',text:error});return false;}s.exerciseId=e.id;if(e.category==='Jumping')s.setup.type=e.id;}if(action==='gait')s.gait=s.gait==='Canter'?'Trot':'Canter';if(action==='ground-pole')s.setup.groundPole=true;if(action==='remove-ground-pole')s.setup.groundPole=false;if(action==='remove-filler'){s.setup.filler=false;if(s.exerciseId==='filler'){s.exerciseId='vertical';s.setup.type='vertical';}}if(action==='object'){s.objectId=(s.objectId||0)+1;s.exerciseId='desensitize';s.setup.filler=true;}if(action==='away-object'){s.objectDistance=(s.objectDistance||1)+2;s.difficulty=Math.max(-2,s.difficulty-1);}if(action==='approach-object'){const before=s.objectDistance||3;s.objectDistance=Math.max(1,before-1);if(s.objectDistance<before)s.difficulty=Math.min(2,s.difficulty+1);}if(action==='smaller-steps')s.difficulty=Math.max(-2,s.difficulty-1);s.adjustedSinceAttempt=true;s.log.push({kind:'Adjustment',text:`${t2extraActions(h,s).find(([a])=>a===action)?.[1]||action}: future attempts use the updated lesson setup.`});if(action==='repeat-line'||action==='calm-repeat')return t2attempt(h,s);if(action==='different-fence'&&s.course){s.courseIndex=(s.courseIndex+1)%s.course.obstacles.length;s.setup={...s.course.obstacles[s.courseIndex]};s.exerciseId=t2courseExercise(s.setup).id;}return true;}

const T2_OLD_BASE_HORSE=baseHorse;
