const T2_STATE=Object.freeze({controlPP:.1,bondPP:.14});
function t2equipmentContext(e,s){return e.category==='Groundwork'?e.id.startsWith('lunge-')?'lunging':'groundwork':e.category==='Flatwork'?s.discipline==='eventing'?'eventing-dressage':s.discipline==='dressage'?'dressage':'flatwork':e.category==='Trail'?'trail':s.discipline==='eventing'?'eventing-jumping':s.discipline==='hunter'?'hunter':'jumping';}

function t2importLegacySchedule(h){const t=t2horse(h);let focus=h.autoTrainingFocus||'';if(t.scheduleEdited)return;const medical=careTrainingStatus(h)==='Medically Restricted / Unrideable';if(!focus&&medical&&t.importedAutoFocus){t.medicalAutoFocus=t.importedAutoFocus;return;}if(!focus&&!medical&&t.medicalAutoFocus){focus=t.medicalAutoFocus;h.autoTrainingFocus=focus;delete t.medicalAutoFocus;}if(t.importedAutoFocus===focus)return;const previous=t.importedAutoFocus;t.importedAutoFocus=focus;if(!focus||['None','Rest'].includes(focus)){if(previous)t.scheduleEnabled=false;return;}if(!['Breaking in','Light Exercise','jumping','dressage','hunter','eventing'].includes(focus))return;const retired=h.retiredForever||h.retiredToBreeding,activity=retired||focus==='Light Exercise'?'Light Exercise':focus==='Breaking in'?'Groundwork':focus==='dressage'?'Dressage':focus==='hunter'?'Hunters':focus==='eventing'?'Eventing Schooling':'Jumping',exerciseId=activity==='Groundwork'?'leading':activity==='Dressage'?'large-circle':activity==='Light Exercise'?'leading':'crossrail';t.scheduleEnabled=true;t.schedule=T2_WEEK.map((_,i)=>[0,2,4].includes(i)?{activity,exerciseId,facilityId:'outdoor',intensity:'Light',mode:'Auto'}:{activity:'Rest',exerciseId:'leading',facilityId:'outdoor',intensity:'Light',mode:'Auto'});}

const T2_GEOMETRY=Object.freeze({widthPPPerMetre:10,maxWidthPP:4});

const T2_OLD_STALL_ELIGIBILITY=stallBehaviorEligible;
stallBehaviorEligible=function(template,h,stall,...args){if([11,12].includes(template.id)){const holder=stallActiveSupplies(stall).find(i=>i.type==='Likit Treat Holder');if(!holder)return false;if(holder.refillFlavor===h.dislikedLikitFlavor)return template.id===12;}return T2_OLD_STALL_ELIGIBILITY(template,h,stall,...args);};

function t2memoryKey(e,s,setup){return ['filler','water','equipment','desensitize'].includes(e.id)?e.memory+'|'+(setup.id||s.objectId||e.id):e.memory;}
function t2suggest(h,s){const ids=s.log.some(x=>x.rushing)?['downward','canter-poles','related']:s.log.some(x=>x.event==='hesitation')?['desensitize','ground-pole','crossrail']:s.log.some(x=>x.event==='distraction')?['standing','large-circle','voice']:s.log.some(x=>x.resultIndex>=3)?['walk-halt','ground-pole','leading']:['large-circle','trot-poles','standing'];return ids.map(t2exercise).filter(e=>!t2eligibility(h,e,{height:.5,location:s.location})).map(e=>e.name);}

const T2_DIFFICULTY_LABELS=['Very Easy','Easy','Appropriate','Challenging','Difficult but permitted'];
for(const e of T2_EXERCISES){e.primarySkill={scope:'learned',name:e.skill};e.secondarySkill={scope:'riding',name:e.secondary};e.technicalErrorCategory=t2taskEvent(e);e.baseDifficulty=e.base<=5?'Easy':e.base<=10?'Appropriate':'Challenging';e.resultMessages=T2_RESULT.map((result,index)=>({result,index}));e.minimumEducation=e.education;e.suitableLocations=e.locations;e.durationPerAttempt=e.duration;e.allowedAdjustments=e.adjustments;}

function t2courseExercise(fence){return t2exercise(fence.combination?(fence.distance<8?'one-stride':'two-stride'):fence.type)||t2exercise('vertical');}

function t2attemptKey(e,setup,s){return JSON.stringify([e.id,s.difficulty,setup.id||'',setup.height,setup.width,setup.distance,setup.direction,Boolean(setup.filler),s.objectId||'']);}

function t2reserveTraining(h,start,minutes,id){const t=t2horse(h),previous=t.trainingSpan;if(previous?.ids?.includes(id))return;if(previous&&previous.end>start&&previous.start<=start){previous.end+=minutes/60;previous.ids.push(id);}else t.trainingSpan={start,end:start+minutes/60,ids:[id]};}
function t2awayInterval(h,hour){const span=h.training2?.trainingSpan;if(!span)return null;const start=Math.max(0,span.start-hour),end=Math.min(1,span.end-hour);return end>start?[start,end]:null;}
const T2_OLD_PASTURE_FRACTION=mgPastureFraction,T2_OLD_TURNOUT_SPAN=careTurnoutSpan;
mgPastureFraction=function(h,hour){const old=T2_OLD_PASTURE_FRACTION(h,hour),away=t2awayInterval(h,hour);if(!old||!away)return old;const span=T2_OLD_TURNOUT_SPAN(h,hour),start=span[0]-hour%24,end=span[1]-hour%24;return Math.max(0,old-Math.max(0,Math.min(end,away[1])-Math.max(start,away[0])));};
careTurnoutSpan=function(h,hour){const span=T2_OLD_TURNOUT_SPAN(h,hour),away=t2awayInterval(h,hour);if(!away)return span;const offset=hour%24;if(away[0]<=Math.max(0,span[0]-offset))span[0]=Math.max(span[0],offset+away[1]);else span[1]=Math.min(span[1],offset+away[0]);return span;};
mgStallFraction=function(h,hour){const away=t2awayInterval(h,hour);return Math.max(0,1-(away?away[1]-away[0]:0)-mgPastureFraction(h,hour));};
mgStallIntervals=function(h,hour){let spans=[[0,1]],blocked=[];const away=t2awayInterval(h,hour);if(away)blocked.push(away);if(T2_OLD_PASTURE_FRACTION(h,hour)>0){const s=T2_OLD_TURNOUT_SPAN(h,hour);blocked.push([s[0]-hour%24,s[1]-hour%24]);}for(const [x,y]of blocked)spans=spans.flatMap(([a,b])=>[[a,Math.min(b,x)],[Math.max(a,y),b]].filter(([a,b])=>b>a));return spans;};

function t2railProfile(h,e,c){const profile=t2probability(h,'railContact',e.base,{...c,statePP:0,eventAliases:['frontRail','hindRail','rail']});let front=e.base/2,hind=e.base/2;for(const [i,trait]of profile.traits.entries()){const pp=trait.value*(i?T2.secondaryTraitWeight:1);if(trait.name==='Careful Front End')front+=pp;else if(trait.name==='Trails Hind Legs')hind+=pp;else{front+=pp/2;hind+=pp/2;}}front=Math.max(0,front);hind=Math.max(0,hind);const sum=front+hind,scale=sum>30?30/sum:1;return {...profile,chance:sum*scale,front:front*scale,hind:hind*scale};}
const T2_CONTEXT_LABELS={jump:'jumping approaches',newFence:'an unfamiliar obstacle',familiarFence:'a familiar fence',comfortableJump:'healthy, comfortable jumping work',shortLine:'an inappropriately short line',longLine:'an inappropriately long line',strongRein:'a strong rein aid',third:'the third identical repetition onward',repeated:'repeated appropriate work',failedRepeat:'an unsuccessful repeated attempt',cold:'before suitable warm-up',newArena:'an unfamiliar arena',busy:'a busy environment',horses:'other visible horses',calmHorses:'calm horses nearby',wind:'significant wind',traffic:'nearby traffic',gate:'near arena gates',roughGroom:'unsuitable grooming',completed:'completed exercises',familiarHandler:'a familiar handler'};

const T2_OLD_RESET=resetGame;
resetGame=function(...args){app.training2=null;return T2_OLD_RESET(...args);};
// Retain the older dedicated handling control, but remove its generic personality failure stacking.
trainingControlabilitySession=function(h,focus){const ground=['Hand Work','Manners'].includes(focus),exercise=t2exercise(ground?'leading':'walk-halt'),error=t2eligibility(h,exercise);if(error){pushReport(error);return null;}const state=t2horse(h),c={ordinary:true,familiarHandler:(h.bond||0)>=40,aid:ground?'both':'rein',statePP:equipmentModifiers(h,ground?'groundwork':'flatwork').fail},profile=t2probability(h,'aid',exercise.base,c,'Responsiveness','Focus'),success=t2random(state)*100>=profile.chance;const delta=success?Math.floor(t2range(5,11,state)):-Math.floor(t2range(1,5,state)),before=h.controlability||0;h.controlability=clamp(before+delta,0,100);pushReport(`${h.name} ${success?'responded to':'struggled with'} ${focus}. Controllability ${h.controlability-before>=0?'+':''}${t2fmt(h.controlability-before)} pp; bounded execution-error chance ${t2fmt(profile.chance)}%.`);return success;};

function t2learningDiscipline(e,s){if(s.discipline==='eventing')return 'eventing';if(['Jumping','Polework'].includes(e.category))return s.discipline==='hunter'?'hunter':'jumping';return 'dressage';}

const T2_OLD_FARRIER_RENDER=renderFarrier;
renderFarrier=function(){T2_OLD_FARRIER_RENDER();const panel=document.getElementById('farrier'),button=panel.querySelector('#do-farrier');if(!button)return;const previous=button.onclick;button.onclick=()=>{const h=t2findHorse(panel.querySelector('#farrier-horse').value),balance=app.money;previous();if(h&&app.money<balance){const profile=t2probability(h,'farrier',t2exercise('hoof').base,{farrier:true},'Patience');if(t2random(t2horse(h))*100<profile.chance)pushReport(`${h.name} became tense during farrier handling. Routine care was completed; consider suitable hoof-handling practice.`);else pushReport(`${h.name} stood quietly during routine hoof care.`);saveGame(false);}};};

function t2mixSeed(value){value=Math.imul(value^(value>>>16),0x7feb352d);value=Math.imul(value^(value>>>15),0x846ca68b);return (value^(value>>>16))>>>0;}

function t2requiredWarmup(h,e){return (e.intensity===3?T2.warmup.demanding:T2.warmup.ordinary)+(h.age>=20?T2.warmup.ageExtra:0)+((h.fatigue||0)>=50?T2.warmup.fatigueExtra:0);}
function t2automaticWarmup(h,s,intensity){const required=t2requiredWarmup(h,{intensity});if(intensity===3){t2warmup(h,s,'walk',required-6);t2warmup(h,s,'trot',4);t2warmup(h,s,'canter',2);}else t2warmup(h,s,'walk',required);}

function t2educationScore(h){return h.age>=3&&canRideUnderSaddle(h)?Math.max(500,h.behavior||0):h.behavior||0;}

function t2syncCourse(s){if(s.course&&s.courseIndex>=0&&s.course.obstacles[s.courseIndex])s.course.obstacles[s.courseIndex]={...s.setup};}

function t2weatherMessages(h,location,weather){const messages=[];if(location==='Indoor'&&weather.precipitation)messages.push('The indoor arena provides shelter from the current precipitation.');if(weather.wind>=25)messages.push('Strong wind is affecting the horse’s concentration.');if(weather.temperature>=34)messages.push('The temperature is unusually high. Intensive training may cause excessive fatigue.');if(location==='Outdoor'&&['Storm','Heavy Snow','Ice'].includes(weather.type))messages.push('Outdoor training is unavailable due to unsafe weather conditions.');if(location==='Outdoor'&&weather.type==='Heavy Rain')messages.push('The outdoor arena footing is unsuitable for jumping after heavy rain.');return messages;}

function t2heightAdjustment(height,comfortable){const diff=Math.round((height-comfortable)*100)/100;return diff<=-.2?T2.heightModifiers.below20:diff<=-.1?T2.heightModifiers.below10:diff>=.2?T2.heightModifiers.above20:diff>=.1?T2.heightModifiers.above10:T2.heightModifiers.at;}

function t2sessionMonth(hour){const date=pastureDate(hour);return date.year*12+date.month;}
function t2recordSession(h,hour){const t=t2horse(h),month=t2sessionMonth(hour);t.sessionCounts=t.sessionCounts||{};t.sessionCounts[month]=(t.sessionCounts[month]||0)+1;for(const key of Object.keys(t.sessionCounts))if(Number(key)<month-12)delete t.sessionCounts[key];}
function t2scheduledSessionCount(h,hour){const own=t2horse(h).sessionCounts?.[t2sessionMonth(hour)]||0;return t2sessionMonth(hour)===currentMonthIndex()?Math.max(own,h.trainingSessionsThisMonth||0):own;}

function t2sessionRisk(h,s,intensity){if((h.fatigue||0)>=70&&intensity>=2||s.difficulty>=2&&intensity===3)return 'high';if(intensity===3){const jumps=s.log.filter(x=>x.exerciseId&&t2exercise(x.exerciseId).category==='Jumping');return jumps.length&&jumps.every(x=>x.exerciseId==='crossrail'&&Number(x.setup?.height??s.setup.height)<=t2height(h)-.2)&&s.difficulty<=0?'low':'medium';}return intensity>=2&&(s.difficulty>=1||s.location==='Outdoor'&&s.weather.type==='Heavy Rain')?'medium':'low';}
